mapper.select:
select a.task_id, IFNULL(a.no_check_num, 0) no_check_num, IFNULL(b.is_check_num, 0) is_check_num, IFNULL(c.py, 0) py, IFNULL(cc.pys, 0) pys, IFNULL(d.pk, 0) pk, IFNULL(dd.pks, 0) pks from ( select task_id, count(id) as no_check_num from idevelop_check_task_device where check_status = '1' and task_id in
#{id}
group by task_id ) a left join ( select task_id, count(id) as is_check_num from idevelop_check_task_device where check_status = '0' and task_id in
#{id}
group by task_id ) b on a.task_id = b.task_id left join ( select task_id, count(id) as py from idevelop_check_task_device where check_status = '2' and task_id in
#{id}
group by task_id ) c on a.task_id = c.task_id left join ( select task_id, count(id) as pys from idevelop_check_task_device where check_status = '2' and dispose_result = '1' and task_id in
#{id}
group by task_id ) cc on a.task_id = cc.task_id left join ( select task_id, count(id) as pk from idevelop_check_task_device where check_status = '3' and task_id in
#{id}
group by task_id ) d on a.task_id = d.task_id left join ( select task_id, count(id) as pks from idevelop_check_task_device where check_status = '3' and dispose_status = '1' and task_id in
#{id}
group by task_id ) dd on a.task_id = dd.task_id

select id, task_id, device_id, ci_id, uuid, device_code, device_name, asset_code_erp, account_code_erp, factory_serial, device_category, device_type, device_status, receive_dept, receive_dept_code,
receiving_person, receiving_tel, `user`, installation_site, ip, mac, check_status, dis_person, dis_time, dispose_result, dispose_status, is_itai_code, filing_no, filing_time, offline_start_time,
offline_end_time
from idevelop_check_task_device

    is_deleted = 0
    
        and task_id = #{dto.taskId}
    
    
        and receive_person_unified_acc = #{dto.account}
    
    
        and receive_dept_code = #{dto.receiveDeptCode}
    
    
        and device_type = #{dto.deviceType}
    
    
        and check_status = #{dto.checkStatus}
    
    
        and change_content != '[]'
    
    
        and device_status = #{dto.deviceStatus}
    
    
        and dispose_status = #{dto.disposeStatus}
    
    
        and ip like concat('%', #{dto.ip}, '%')
    
    
        and mac like concat('%', #{dto.mac}, '%')
    
    
        and device_name like concat('%', #{dto.deviceName}, '%')
    
    
        and is_itai_code = #{dto.isItaiCode}
    
    
        and sub_person like concat('%', #{dto.subPerson}, '%')
    
    
        and sub_tel like concat('%', #{dto.subTel}, '%')
    
    
        and check_status in
        
            #{status}
        
        or dispose_result in
        
            #{status}
        
    

order by update_time DESC

select count(id) from idevelop_check_task_device
where  dispose_result = '5' and task_id = #{id}
and is_deleted = 0

select count(id) from idevelop_check_task_device
where  dispose_result = '3' and task_id = #{id}
and is_deleted = 0
